// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.authimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Queryimport androidx.room.Update/** * NOUS — PIN hash DAO (Module 12, Pillar 3 — SQLCipher-backed). * * Strategy §12.3 — Room DAO that persists [PinHashEntity] inside the * SQLCipher-encrypted [SecurityDatabase]. Injected into [SqlCipherPinStorage] * via Hilt. * * All methods are `suspend` so they run on a Room dispatching executor — * safe to call from a `Dispatchers.IO` coroutine scope. * * @see PinHashEntity * @see SqlCipherPinStorage */@Daointerface PinHashDao {    /**     * Upsert the PIN row. Because [PinHashEntity.id] is fixed at `0`     * (singleton), `REPLACE` semantics overwrite any existing PIN.     */    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun upsert(entity: PinHashEntity)    /**     * Load the singleton PIN row. Returns `null` if no PIN is set.     */    @Query("SELECT * FROM pin_hash WHERE id = 0 LIMIT 1")    suspend fun get(): PinHashEntity?    /**     * Update the failed-attempt counter + lockout deadline without     * rewriting the hash (avoids re-hashing on every failed attempt).     */    @Query("UPDATE pin_hash SET failed_attempts = :failedAttempts, locked_until_ms = :lockedUntilMs WHERE id = 0")    suspend fun updateLockoutState(failedAttempts: Int, lockedUntilMs: Long)    /**     * Delete the singleton PIN row. Used by "disable app lock".     */    @Query("DELETE FROM pin_hash WHERE id = 0")    suspend fun delete()}